// ===================== QUIZ DATA =====================
const qzData=[{"q":"¿Qué es lo único que separa «el rey murió y luego murió la reina» de «el rey murió y luego murió la reina de pena»?","o":["a) La causa que une los dos hechos","b) El orden de los hechos","c) La cantidad de personajes","d) El tono de la frase"],"c":0,"e":"Los dos hechos y su orden son idénticos. Lo que se añade son dos palabras que dicen POR QUÉ, y eso convierte una crónica en historia. Es la prueba de Forster en «Aspects of the Novel» (1927)."},{"q":"En la prueba del conector, ¿qué significa que entre dos golpes solo quepa «y entonces»?","o":["a) Que ese eslabón no existe: ahí no hay causa, hay reloj","b) Que la frase está mal escrita","c) Que falta un adjetivo","d) Que hay demasiada información"],"c":0,"e":"«Y entonces» solo dice que una cosa pasó después de otra, y el calendario no es una causa. La prueba la dieron Trey Parker y Matt Stone en una clase en la Universidad de Nueva York (2011)."},{"q":"Según el trabajo de Loewenstein (1994), ¿qué enciende la curiosidad?","o":["a) El hueco entre lo que uno sabe y lo que se da cuenta de que le falta","b) La cantidad de información disponible","c) La novedad del tema","d) La emoción con que se cuenta"],"c":0,"e":"Es la teoría del hueco de información, y tiene una consecuencia práctica incómoda: quien empieza explicando todo el contexto apaga el motor, porque a un oyente al que no le falta nada no le queda motivo para seguir."},{"q":"Un video empieza diciendo «hoy vamos a hablar de la nueva misión de fracciones, que sirve para practicar». ¿Qué falla, en el vocabulario de esta etapa?","o":["a) La cadena, porque no hay hechos","b) La brecha, porque el resultado fue el esperado","c) El hueco: en el minuto uno ya no le falta nada al que mira","d) El obstáculo, porque no hay antagonista"],"c":2,"e":"Ese arranque entrega de qué va, para qué sirve y cómo acaba. No es que sea aburrido: es que no deja nada por saber, y sin hueco no hay motivo para quedarse."},{"q":"¿Cuál de estos tres huecos se gasta en un segundo y no se puede repetir en el mismo texto?","o":["a) La curiosidad","b) El suspenso","c) Los tres duran lo mismo","d) La sorpresa"],"c":3,"e":"En el reparto de Sternberg («Telling in Time», 1990 y 1992), la sorpresa es el hueco escondido: es el más fácil de escribir y el que menos dura. Sostiene una frase, no un texto entero."},{"q":"Alguien cuenta: «pedimos permiso a la Secretaría, lo dieron, empezamos». ¿Qué le falta para ser una historia?","o":["a) Un obstáculo humano","b) La brecha: todo salió como se esperaba","c) Más detalles sensoriales","d) Un final abierto"],"c":1,"e":"Sin resultado inesperado no hay historia, hay acta, y un acta bien escrita también sirve. Lo que NO se hace es inventarle un antagonista para forzarla."},{"q":"En la ficha de hilo, ¿por qué no vale «la vida» o «el sistema» como obstáculo?","o":["a) Porque suena pesimista","b) Porque un obstáculo abstracto no genera ninguna escena que se pueda contar","c) Porque son temas políticos","d) Porque son demasiado largos de explicar"],"c":1,"e":"El obstáculo tiene que poderse ver: otra persona, una regla, un plazo, o la propia contradicción del que quiere. Si no se ve, la historia solo se puede resumir."},{"q":"Bower y Clark (1969) compararon memorizar listas de palabras con encadenarlas en una historia. ¿Qué encontraron?","o":["a) No hubo diferencia apreciable","b) El grupo que encadenó recordó alrededor de siete veces más","c) Las listas se recordaron mejor por ser más cortas","d) El efecto solo apareció en niños"],"c":1,"e":"El mismo material, la misma gente y el mismo tiempo. Lo único distinto era que unas palabras estaban atadas y las otras en fila. Trabasso y van den Broek (1985) precisaron después que lo que ayuda no es «la historia» sino la causa."},{"q":"Green y Brock (2000) midieron que meterse en un relato reduce la contraargumentación. ¿Qué regla saca de ahí esta casa?","o":["a) Que conviene contar historias en vez de dar datos","b) Que los datos no convencen a nadie","c) Que hay que evitar las historias en asuntos serios","d) Que la historia se cuenta para que se entienda el dato, nunca para que no se pida"],"c":3,"e":"El hallazgo dice que esto es un arma, no que sea gratis. Por eso la historia y la tabla completa van en la misma página, y no la tabla en un anexo."},{"q":"El estudio de Reagan y colegas (2016) midió el arco emocional de 1.327 obras. ¿Cuál es su límite declarado?","o":["a) Que midió solo novelas cortas","b) Que no usó ningún método estadístico","c) Que el corpus del Proyecto Gutenberg es casi todo literatura occidental en inglés","d) Que las seis formas no se pueden dibujar"],"c":2,"e":"Es el dato más duro de la materia y trae escrito su propio límite: dice mucho de nuestras historias y poco de las de la humanidad entera. Por eso el careo de esta etapa termina pidiendo el mismo estudio con otro corpus."}];
let qzIdx=0,qzSel=-1,qzDone=false;
function buildQz(){qzIdx=0;qzSel=-1;qzDone=false;showQz();}
function showQz(){if(qzIdx>=qzData.length){document.getElementById('qzQ').textContent='🎉 ¡Quiz completado!';document.getElementById('qzOpts').innerHTML='';fin('s-quiz');unlockAchievement('primer_quiz');return;}const q=qzData[qzIdx];document.getElementById('qzProg').textContent=`Pregunta ${qzIdx+1} de ${qzData.length}`;document.getElementById('qzQ').textContent=q.q;const opts=document.getElementById('qzOpts');opts.innerHTML='';q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(qzDone)return;document.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');qzSel=i;sfx('click');};opts.appendChild(b);});qzDone=false;}
function checkQz(){if(qzSel<0)return fb('fbQz','Selecciona una respuesta.',false);qzDone=true;const opts=document.querySelectorAll('.qz-opt');if(qzSel===qzData[qzIdx].c){opts[qzSel].classList.add('correct');fb('fbQz','¡Correcto! +5 XP',true);if(!xpTracker.qz.has(qzIdx)){xpTracker.qz.add(qzIdx);pts(5);}sfx('ok');}else{opts[qzSel].classList.add('wrong');opts[qzData[qzIdx].c].classList.add('correct');fb('fbQz','Incorrecto. Revisa la respuesta correcta.',false);sfx('no');}setTimeout(()=>{qzIdx++;qzSel=-1;showQz();},1600);}
function resetQz(){sfx('click');qzIdx=0;qzSel=-1;qzDone=false;showQz();document.getElementById('fbQz').classList.remove('show');}

