function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt": "EL VIDEO QUE EMPIEZA EXPLICANDO. Hay que grabar el sábado el video de una misión nueva de M.E.T.A.S, de siete minutos. El borrador tiene nueve párrafos y abre con «hoy vamos a hablar de la nueva misión de fracciones, que sirve para que los alumnos de cuarto grado practiquen»; después explica para qué sirve, luego cómo se hizo, y en el párrafo nueve aparece una alumna que llevaba dos años sin aprobar matemáticas. Grabar cuesta seis horas entre dos personas. Los nueve párrafos van unidos con «además» y «y entonces»."}, {"txt": "EL INFORME QUE NADIE LEE. Un patrocinador pide un informe de una página sobre el año de M.E.T.A.S. La familia manda doce cifras, todas comprobables: 40 aulas, 1,240 cuentas de maestras, 63 misiones, 8 meses sin incidentes cuando el año anterior hubo tres. Tres semanas después el patrocinador pregunta en una reunión «¿y esto para qué sirve?». Nadie recuerda ninguna de las doce cifras."}, {"txt": "LA MAESTRA QUE SÍ LO USÓ. El mejor material de la casa es una maestra de un centro rural que usó M.E.T.A.S dos años seguidos con 22 alumnos. Se cuenta así: «le gustó la aplicación, la usó todo el año, los alumnos mejoraron y sigue usándola». En una llamada, además, ella contó que el primer mes lo dejó, y que volvió por algo que nadie ha vuelto a preguntar."}, {"txt": "LA PUBLICACIÓN DE ANIVERSARIO. Se cumplen tres años de M.E.T.A.S y el borrador es una cronología: «en 2023 empezamos con dos misiones, en 2024 llegamos a treinta, este año vamos por sesenta y tres». Se piensa acompañarla con nueve imágenes y un video de dos minutos, unas cinco horas de trabajo. El año en que se pasó de dos a treinta misiones fue el año en que no había servidor, y eso no está en el borrador."}, {"txt": "LOS CINCO MINUTOS ANTE LA SECRETARÍA. Hay reunión con una dirección departamental y la casa tiene cinco minutos antes de las preguntas. El guion dedica los dos primeros a explicar qué es M.E.T.A.S, quiénes son la familia y cómo se financia; en los tres restantes entran los números y, si alcanza, un caso. La reunión se consiguió después de cuatro meses pidiéndola. El dato de las once escuelas que dejaron de usarlo no está en el guion."}, {"txt": "LA HISTORIA QUE PIDE DINERO. Una convocatoria de L 60,000 pide una página. Hay dos maneras de llenarla: las 1,240 cuentas de maestras con sus cifras de uso, o la historia de una niña de un centro rural. Quien ha hecho esto antes avisa de que la historia de la niña recauda más. Nadie ha preguntado todavía si la niña o su familia dieron permiso por escrito."}, {"txt": "EL MENSAJE DE VOZ DE LAS ONCE DE LA NOCHE. Un maestro pregunta por WhatsApp qué es M.E.T.A.S. La respuesta escrita, preparada y revisada, tiene ocho líneas y no la contesta nadie. Dos semanas después se le manda a otra persona un mensaje de voz de cincuenta segundos, sin preparar y con el ventilador de fondo: «esto empezó porque mi hija de nueve años no entendía las fracciones y en la escuela no había con qué; hicimos una cosa en el teléfono; pero al final la que más lo usó fue la maestra». Ese maestro contesta en cuatro minutos y en dos días instala el APK."}, {"txt": "LA RESEÑA DE UNA ESTRELLA. En la tienda de aplicaciones aparece una reseña de una estrella: «no sirve, la instalé y no abre». Es la única mala entre treinta y ocho. La causa técnica está identificada: el APK sin conexión necesita 180 megabytes libres y ese teléfono no los tenía. En el grupo se proponen dos cosas: contestar con la explicación técnica, o pedir a los conocidos que suban reseñas buenas para taparla."}];
const critCaseQuestions=["1. Pasa el material a columna y marca dónde se rompe la cadena: escribe entre qué dos golpes solo cabe «y entonces», y por qué ahí no hay causa.", "2. Escribe el hueco en UNA frase: qué es exactamente lo que el que escucha (el patrocinador, el maestro, la dirección departamental, quien mira el video) todavía no sabe y le va a importar. Di además de cuál de los tres huecos se trata: pasado, futuro o escondido.", "3. Di si hay brecha o si esto es un acta. Si la hay, escríbela en una línea: qué se esperaba y qué salió. Si no la hay, di dónde iría a buscarla o por qué este material se queda en acta.", "4. Llena las casillas que falten de la ficha de hilo (quién, qué quiere, qué se lo impide, qué hace y qué le sale, qué se sabe al final) y escribe con qué arranque de dos frases lo contarías."];
const critCaseGuides=["Se valora que la columna exista de verdad, con un hecho por línea, y que el eslabón roto se señale entre dos golpes concretos y no en general. No se valora decir «le falta hilo» ni «está mal ordenado»: hay que poder citar las dos líneas entre las que solo cabe «y entonces». Se valora también quien note que la mayoría de estos materiales no tienen un eslabón roto sino casi todos, y que la salida no es añadir causas inventadas sino quedarse con los golpes que de verdad se causan entre sí, aunque queden menos.", "Se valora que el hueco esté escrito en una sola frase y en términos del que escucha, no del que cuenta: qué le falta a ÉL. No se valora un hueco que sea el tema («voy a hablar de seguridad») ni un final oculto por gusto de ocultarlo. Se valora que se identifique el tipo con el reparto de Sternberg, y que se justifique la elección: la curiosidad aguanta un texto entero, el suspenso pide que importe alguien, y la sorpresa se gasta en un segundo, así que elegirla para abrir un video de siete minutos es un error de duración y hay que decirlo.", "Se valora que la respuesta distinga con honradez la historia del acta, y que no se fuerce una brecha donde no la hay. Un acta declarada como acta vale como respuesta completa. Cuando la brecha existe pero está tapada, se valora que se diga dónde: casi siempre en el trozo que la versión oficial se salta por incómodo (el mes en que lo dejó, el año sin servidor, las once escuelas que se fueron, la queja de una estrella). Y se valora quien añada el límite ético: si la brecha está en la vida de otra persona, hace falta su permiso antes de contarla.", "Se valora que las cinco casillas se entiendan sin conocer el caso, y sobre todo que la casilla del obstáculo tenga cara: una persona, una regla, un plazo o una contradicción propia, nunca «la vida» ni «el sistema». En el arranque de dos frases se valora que no haya presentación ni contexto, que se abra por el hueco elegido en la pregunta 2 y que la primera frase no revele el final. Y se valora quien escriba también el freno cuando el caso lo pide: la historia arriba y la tabla completa debajo, en la misma página, nunca en un anexo."];
const critErrorBank=[{"txt": "«El video quedó flojo, le vamos a meter música y unos adjetivos más fuertes.»", "g1": "Confunde un defecto de arquitectura con un defecto de tono. Si el borrador no tiene cadena ni hueco, la música y los adjetivos no añaden ninguna de las dos: subrayan una lista.", "g2": "Se corrige antes de tocar el tono: los golpes a columna, los conectores puestos, y una frase escrita con lo que el que mira todavía no sabe. Después, si hace falta, música."}, {"txt": "«Esta historia no funciona porque no hay un malo. Vamos a pintar a la Secretaría como el obstáculo.»", "g1": "Convierte una herramienta en un requisito y paga el precio: inventa un antagonista que no existía, y encima en no ficción, donde eso ya no es un error técnico.", "g2": "Se corrige aceptando que el conflicto es opcional y el hueco no. Si no hay obstáculo real, se busca la brecha (qué salió distinto de lo esperado) o se escribe como acta. Le Guin (1986) y Alison (2019) están publicadas justo contra esta maniobra."}, {"txt": "«Para que se entienda bien, empecemos explicando quiénes somos, qué hacemos y cómo nos financiamos.»", "g1": "Cierra el hueco en el minuto uno. Con todo el contexto entregado, al que escucha no le falta nada, y sin falta no queda ningún motivo para seguir escuchando (Loewenstein, 1994).", "g2": "Se corrige moviendo el contexto al lugar donde el que escucha ya lo necesite para seguir, y abriendo por lo que no cuadra. El «quiénes somos» cabe en una frase o se manda por escrito antes de la reunión."}, {"txt": "«La cronología es lo más honrado: cuenta lo que pasó, en orden, sin interpretar nada.»", "g1": "Es honrada y es una crónica. Su único hilo es el calendario, y el calendario no es una causa: es exactamente el caso del rey y la reina sin el «de pena» (Forster, 1927).", "g2": "Se corrige sin renunciar a la honradez: la cronología completa va en una tabla al pie, y arriba se cuenta un año y una brecha. Lo cierto no se quita; se le pone un hilo."}, {"txt": "«La historia de la niña recauda más que las mil doscientas cuarenta cuentas, así que mandamos solo la historia.»", "g1": "Usa el efecto medido del relato para que el dato no se pida. Green y Brock (2000) explican por qué funciona, y eso es el motivo para tener una regla, no el permiso para no tenerla.", "g2": "Se corrige poniendo la historia arriba y las cifras completas debajo, en la misma página y no en un anexo. Y con el permiso por escrito de la niña o de su familia: sin eso, la historia no sale aunque valga sesenta mil lempiras."}, {"txt": "«El mensaje de voz gustó porque yo hablo bien; lo que hay que hacer es grabar más audios.»", "g1": "Atribuye el resultado al talento del que habla y no al material. Lo que el mensaje tenía eran un porque, un pero y un hueco, y eso se puede escribir; el carisma no se puede repetir a voluntad.", "g2": "Se corrige transcribiendo el mensaje que funcionó el mismo día y marcando sus conectores. Lo que se guarda en el Cuaderno de Hilos es la cadena, no el tono de voz."}];
const critDecisionBank=["El video se graba el sábado y el borrador abre explicando la misión: ¿se graba así, se posterga o se reordena antes? Di qué párrafo va primero y por qué.", "El patrocinador ya preguntó «para qué sirve esto»: ¿se manda otra página de cifras, se manda una historia, o se manda otra cosa? Escribe qué lleva arriba y qué lleva debajo.", "La maestra contó que el primer mes lo dejó: ¿se usa ese dato, se omite, o se pregunta antes? Di a quién se pregunta y qué se hace si ella pide que no se cuente.", "El aniversario se publica el viernes: ¿cronología de tres años o un año con una brecha? Di qué año eliges y cuál es la brecha.", "Quedan cinco minutos ante la dirección departamental: ¿dónde se ponen los dos minutos de presentación? Escribe las dos primeras frases que dirías.", "La convocatoria son sesenta mil lempiras: ¿se manda la historia de la niña, las cifras, o las dos? Di en qué orden y qué falta conseguir antes de mandar nada.", "El mensaje de voz funcionó y el escrito no: ¿se cambia la respuesta oficial, se deja como está, o se hace algo más? Di qué se guarda y dónde.", "La reseña de una estrella lleva dos días publicada: ¿se contesta, se tapa con reseñas buenas, o se hace otra cosa con ella? Di qué se le responde a esa persona y qué se escribe aparte."];
const critDecisionGuide="La decisión se puntúa por el procedimiento con que se llegó a ella y no por lo audaz que suene. Se valora que se diga qué se escribe, cuándo y quién lo escribe: la columna de golpes con sus conectores, la frase del hueco, la línea de la brecha. Se valora que la respuesta no se cierre con «hay que contarlo mejor», que es la fórmula que esta etapa viene a sustituir. Se valora la honradez cuando el material no da historia: decir «esto es un acta y se manda como tabla» es una respuesta correcta y completa. Se valora que el freno aparezca donde toca: la historia y las cifras completas en la misma página, y el permiso por escrito antes de contar la vida de otra persona. Y se valora que la decisión sea reversible o comprobable: un arranque se prueba leyéndoselo a alguien de la casa antes de grabar, y eso cuesta cinco minutos.";
// El molde imprime también cmp.gr (la síntesis de la pauta): la etapa 1 no
