// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y": "s. IV a. C.", "icon": "🏛️", "label": "Aristóteles", "text": "En la <strong>«Poética»</strong>, Aristóteles pide que la acción sea un todo con principio, medio y fin, describe la <strong>peripecia</strong> (el giro por el que la acción se vuelve al lado contrario) y el <strong>reconocimiento</strong>, y en el capítulo IX distingue al historiador, que cuenta lo que sucedió, del poeta, que cuenta lo que podría suceder. <strong>Por qué importa aquí:</strong> es la primera vez que se dice por escrito que una historia no es una sucesión de hechos, sino algo con forma."}, {"y": "1863", "icon": "📐", "label": "Freytag", "text": "Gustav Freytag publica <strong>«Die Technik des Dramas»</strong> y dibuja la escalada de la acción hasta un clímax, con su descenso: la pirámide que hoy se enseña en las escuelas sin decir de quién es. <strong>Por qué importa aquí:</strong> es el ejemplo perfecto de la regla de oro de esta ruta, una estructura con autor y año a la que se le olvidó la etiqueta y que salió del drama alemán de cinco actos, no de la naturaleza."}, {"y": "1927", "icon": "👑", "label": "Forster", "text": "En las conferencias Clark de Trinity College, Cambridge, E. M. Forster expone lo que se publicará como <strong>«Aspects of the Novel»</strong>: «el rey murió y luego murió la reina» es un relato; «el rey murió y luego murió la reina <strong>de pena</strong>» es una trama. Y añade la mitad que casi nadie cita: ante la primera se pregunta «¿y después?», ante la segunda «¿por qué?». <strong>Por qué importa aquí:</strong> es la prueba entera de esta etapa, en siete palabras."}, {"y": "1969", "icon": "🧠", "label": "Bower y Clark", "text": "Gordon Bower y Michael Clark publican en <strong>«Psychonomic Science»</strong> el experimento que compara memorizar listas de palabras con encadenarlas en pequeñas historias: el grupo que encadenó recordó alrededor de <strong>siete veces más</strong>. <strong>Por qué importa aquí:</strong> el mismo material, la misma gente y el mismo tiempo. Lo único distinto era que unas palabras estaban atadas y las otras en fila."}, {"y": "1985", "icon": "🔗", "label": "Trabasso y van den Broek", "text": "Tom Trabasso y Paul van den Broek publican en el <strong>«Journal of Memory and Language»</strong> que, dentro de un mismo relato, los sucesos con <strong>más conexiones causales</strong> se recuerdan mejor que los que solo van seguidos. <strong>Por qué importa aquí:</strong> aprieta el tornillo del hallazgo anterior. No es «la historia» lo que ayuda a la memoria: es la causa, y un cuento mal atado se olvida como una lista."}, {"y": "1994", "icon": "🕳️", "label": "Loewenstein", "text": "George Loewenstein publica en <strong>«Psychological Bulletin»</strong> «The psychology of curiosity», donde ordena décadas de experimentos alrededor de una idea: la curiosidad responde al <strong>hueco</strong> entre lo que alguien sabe y lo que se da cuenta de que le falta. <strong>Por qué importa aquí:</strong> es el respaldo del hueco, y de él sale la consecuencia práctica más contraintuitiva de la etapa, que explicar todo el contexto apaga el motor."}, {"y": "2016", "icon": "📈", "label": "Reagan y colegas", "text": "Andrew Reagan, Lewis Mitchell, Dilan Kiley, Christopher Danforth y Peter Dodds publican en <strong>«EPJ Data Science»</strong> el arco emocional de <strong>1.327 obras</strong> del Proyecto Gutenberg, reducido a seis formas básicas. <strong>Por qué importa aquí:</strong> es el dato más duro que tiene esta materia y trae escrito su propio límite, porque el corpus es casi todo literatura occidental en inglés. Por eso el careo de esta etapa termina pidiendo el mismo estudio con otro corpus."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ============ SIMULACIÓN: EL SUSTO ANTES DE LA CUENTA ============
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(sacoLaCuenta){sfx(sacoLaCuenta?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(sacoLaCuenta){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">📊</span><span class="ms-text"><strong>Escribiste la cuenta antes de votar:</strong> un incidente en cuarenta aulas durante ocho meses. La tasa cabe en una línea y se puede poner al lado de lo que cuesta la medida: cuarenta horas de trabajo y las aulas sin señal que quedarían fuera.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🧭</span><span class="ms-text"><strong>La reunión discutió la tasa y no el susto:</strong> se dejó el APK sin conexión, se puso el bloqueo por clave en el aparato y quedó apuntada la cuenta, para volver a mirarla cuando haya un segundo incidente.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">😰</span><span class="ms-text"><strong>Se decidió con el caso de la semana:</strong> se suspendió el APK sin conexión el viernes. Cuarenta horas de trabajo, las aulas sin señal fuera del proyecto, y nadie llegó a escribir cuántos incidentes hubo entre cuántas aulas.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🧠</span><span class="ms-text"><strong>Se compró tranquilidad, no seguridad:</strong> la facilidad para recordar el robo hizo de tasa, que es exactamente la disponibilidad trabajando. Cuando el recuerdo se enfríe, la medida seguirá puesta y su costo también.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
// Las llaves del laboratorio (esperado, paradoja, utilidad, ruina) se HEREDAN
// del molde a propósito: los botones del HTML llaman labShowParte('esperado')
// etc., y renombrarlas aquí sin tocar ese archivo rompería el laboratorio en
// silencio. El nombre visible sale de cada «nombre», nunca de la llave. En
// esta etapa el reparto es: esperado = representatividad, paradoja =
// disponibilidad, utilidad = anclaje, ruina = regresión a la media.
const parteData={"esperado": {"nombre": "La cadena", "icon": "🪢", "estructura": {"title": "Qué es", "info": "• Lo que ata un hecho al siguiente: <strong>la causa</strong>, no el reloj<br>• «El rey murió y luego murió la reina» contra «murió la reina <strong>de pena</strong>» (E. M. Forster, «Aspects of the Novel», <strong>1927</strong>)<br>• Ante una crónica el que escucha pregunta «¿y después?»; ante una cadena pregunta «<strong>¿por qué?</strong>»<br>• Es la pieza que hace que haya que recordar lo anterior para entender lo siguiente"}, "funcion": {"title": "Cómo se comprueba", "info": "• Los golpes en <strong>columna</strong>, un hecho por línea<br>• Entre cada dos, una sola palabra de tres permitidas: <strong>pero</strong>, <strong>por eso</strong>, <strong>y entonces</strong><br>• Cada «y entonces» es un <strong>eslabón roto</strong> y se marca<br>• La prueba la dieron Trey Parker y Matt Stone en la Universidad de Nueva York (<strong>2011</strong>), y se hace en dos minutos"}, "enfermedades": {"title": "Dónde se cae", "info": "• En la <strong>cronología</strong>: «en 2023 empezamos, en 2024 crecimos». Su único hilo es el calendario<br>• En el <strong>informe de cifras</strong>: doce hechos ciertos que no se deben nada entre sí<br>• En el texto que <strong>se puede leer en cualquier orden</strong> sin que se note: esa es la señal<br>• Y en el arreglo equivocado, que es meter adjetivos donde falta una causa"}, "cuidados": {"title": "En esta casa", "info": "• Ningún video, informe ni publicación sale sin haber pasado por la <strong>columna de conectores</strong><br>• Se cuenta <strong>cuántos eslabones se rompieron</strong>: si el resultado es «quedó mejor», el ejercicio no se hizo<br>• Cuando no aparece la causa, el golpe <strong>se sale</strong> del texto, aunque sea cierto<br>• La cronología completa no se tira: baja al pie, en una tabla"}}, "paradoja": {"nombre": "El hueco", "icon": "🕳️", "estructura": {"title": "Qué es", "info": "• Lo que el que escucha <strong>nota que le falta</strong>, y que es lo que sostiene su atención<br>• George Loewenstein, «Psychological Bulletin», <strong>1994</strong>: la curiosidad no la enciende la información, la enciende el hueco<br>• No es lo que el narrador esconde: es lo que al otro le falta, y puede crecer <strong>contándole más</strong><br>• Es el <strong>requisito</strong> de esta ruta: sin conflicto se puede contar; sin hueco, no"}, "funcion": {"title": "Cómo se comprueba", "info": "• Se escribe en <strong>una sola frase</strong>: «lo que esta persona todavía no sabe es…»<br>• Si la frase no sale, todavía no hay por dónde empezar<br>• Se elige de qué tipo es, en el reparto de Meir Sternberg (<strong>1990 y 1992</strong>): pasado (curiosidad), futuro (suspenso) o escondido (sorpresa)<br>• Y se comprueba el orden: el hueco se abre al principio y se cierra al final, no antes"}, "enfermedades": {"title": "Dónde se cae", "info": "• En el arranque que <strong>explica el contexto completo</strong>: «hoy vamos a hablar de…»<br>• En los dos minutos de presentación de una reunión de cinco<br>• En elegir la <strong>sorpresa</strong> para abrir algo largo: se gasta en un segundo<br>• Y en confundir hueco con truco: un final ocultado por gusto no es un hueco, es una trampa que el que escucha nota"}, "cuidados": {"title": "En esta casa", "info": "• Nada empieza por el contexto: <strong>el hueco primero</strong>, la explicación cuando ya haga falta<br>• El «quiénes somos» cabe en una frase o se manda por escrito <strong>antes</strong><br>• Los cinco minutos se ensayan con reloj, porque cinco sin ensayar son siete<br>• Y el hueco se apunta en el Cuaderno de Hilos junto con la ficha: es la mitad que se olvida"}}, "utilidad": {"nombre": "La brecha", "icon": "🎯", "estructura": {"title": "Qué es", "info": "• La distancia entre lo que el que quiere algo <strong>esperaba</strong> y lo que el mundo le devolvió<br>• Robert McKee la pone en el centro de <strong>«Story» (1997)</strong>: manual de oficio con autor y año, no hallazgo de laboratorio<br>• Sus formas: salió lo contrario · se consiguió y no servía · se perdió y convenía · <strong>lo dieron a la primera y eso era el problema</strong><br>• Es lo que separa una historia de un acta"}, "funcion": {"title": "Cómo se comprueba", "info": "• Se mira el resultado: <strong>¿salió lo esperado?</strong> Si sí, no hay brecha<br>• Se escribe en una línea: qué se esperaba y qué salió<br>• Si no aparece, se busca en el <strong>trozo que la versión oficial se salta</strong> por incómodo<br>• Y si de verdad no existe, se declara: «esto es un acta», que también es un resultado"}, "enfermedades": {"title": "Dónde se cae", "info": "• En el testimonio ordenado: «pedimos permiso, lo dieron, empezamos»<br>• En la versión pulida que quita el mes en que aquello no funcionó<br>• En <strong>inventar un antagonista</strong> para que parezca historia, que en no ficción ya no es un defecto técnico<br>• Y en la frase «no tenemos nada que contar», que casi siempre significa que falta la brecha, no el material"}, "cuidados": {"title": "En esta casa", "info": "• Se va a preguntar por el trozo incómodo <strong>antes</strong> de escribir una línea<br>• Si la brecha está en la vida de otra persona, hace falta su <strong>permiso por escrito</strong><br>• Un acta declarada como acta se manda como tabla y nadie pierde el tiempo<br>• Y la queja, el fallo y lo que se arregló valen más que treinta y ocho reseñas buenas, porque además son verdad"}}, "ruina": {"nombre": "La ficha de hilo", "icon": "📋", "estructura": {"title": "Qué es", "info": "• Las <strong>cinco casillas</strong> donde se apuntan las tres piezas: quién · qué quiere · qué se lo impide · qué hace y qué le sale · qué se sabe al final<br>• No es una pieza: es <strong>donde se apuntan</strong>, y sin ella lo aprendido se queda en la cabeza y se evapora<br>• Vive en el <strong>Cuaderno de Hilos</strong>, en la Bóveda de F.A.R.O y no dentro de una misión<br>• Es el producto que atraviesa las doce etapas de la ruta"}, "funcion": {"title": "Cómo se comprueba", "info": "• Las cinco casillas se tienen que entender <strong>sin conocer el caso</strong><br>• Ninguna casilla admite un <strong>adjetivo</strong> como contenido: «fue muy emocionante» es una opinión sobre el material, no una pieza<br>• Una casilla vacía <strong>se escribe como vacía</strong>: saber qué falta es un resultado<br>• Y la prueba final: contar lo mismo en treinta segundos y ver si las tres piezas sobreviven"}, "enfermedades": {"title": "Dónde se cae", "info": "• En el <strong>quién institucional</strong>: «la Secretaría decidió». Nadie se identifica con una institución<br>• En el objetivo invisible: «ser feliz», «mejorar la educación». Sin poder ver si se consigue, no hay final posible<br>• En el obstáculo sin cara: <strong>«la vida», «el sistema»</strong><br>• Y en rellenar la casilla 4 con lo que se esperaba, que es la manera silenciosa de quedarse sin brecha"}, "cuidados": {"title": "En esta casa", "info": "• Se llena <strong>antes</strong> de escribir la primera frase, no después<br>• Lo que funcionó se transcribe <strong>el mismo día</strong>: lo que no se apunta esa noche se pierde<br>• Se guarda <strong>con fecha</strong>, porque dentro de un año la memoria va a jurar que el borrador siempre estuvo así<br>• Y las fichas se releen antes de una convocatoria: tener diez historias listas evita inventar una con prisa"}}};
let labParte='esperado',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`⚙️ Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== LECTURAS (normas 5, 5-quater y 5-quinquies) =====================
// Seis textos (Borges, Cervantes, Harari, la entrevista de la casa, la
// conversación Quintero-Gala y el careo) con tres baterías: comprensión (30,
// cinco por voz), completar (12) y análisis complejo (12, sin XP a propósito).
// El armado en pantalla lo hace js/lecturas.js leyendo estos bancos; aquí
// viven los bancos y la impresión. Las preguntas se contestan con los textos
// delante: son examen de lectura, no de memoria.
const lectComprensionBank=[{"t":"Borges","q":"¿En qué consistía exactamente el oficio de Anselmo Sotelo, el cronista?","o":["a) Explicar por qué ocurrían las cosas del pueblo","b) Levantar cada año el padrón de la comarca","c) Recoger las historias que contaba la gente","d) Anotar lo que ocurría, en el orden en que ocurría, sin añadir nada"],"c":3},{"t":"Borges","q":"¿Qué añadía Rosaura Andrade al contar la muerte del caballo del alcalde?","o":["a) Una fecha exacta que Sotelo había olvidado","b) Un testigo que había visto morir al animal","c) La causa: que murió de sed porque el alcalde había mandado cerrar la acequia","d) Una descripción del caballo y de su color"],"c":2},{"t":"Borges","q":"Cuando el narrador le pide a un niño la historia del obispo, ¿qué contesta el niño y qué entiende el narrador?","o":["a) Que el obispo nunca existió, y el narrador entiende que Sotelo mentía","b) Que del obispo no hay nada, y el narrador entiende que lo que no se ata a nada no se guarda","c) Que la historia es demasiado larga, y el narrador entiende que hay que resumir","d) Que se la contó la señora Andrade, y el narrador entiende que ella inventaba"],"c":1},{"t":"Borges","q":"¿Qué hizo Sotelo en el cuaderno cuarenta y dos, y qué descubrió?","o":["a) Escribió dos columnas, el hecho y la palabra que lo ataba al anterior, y descubrió que casi todo era «y entonces»","b) Copió los cuarenta y un cuadernos anteriores en limpio","c) Empezó a anotar también lo que contaba la gente del pueblo","d) Dejó de anotar hechos y se puso a escribir sus opiniones"],"c":0},{"t":"Borges","q":"Según el final del cuento, ¿cuál es la única línea de los cuarenta y dos cuadernos que el narrador se aprendió sin querer?","o":["a) La del caballo del alcalde y la acequia","b) La primera línea del cuaderno número uno","c) La de las seis líneas sobre el obispo","d) La de la muerte de la Andrade, donde Sotelo usa un «por eso» sobre sí mismo"],"c":3},{"t":"Cervantes","q":"¿Qué dos relaciones del robo de las mulas se enfrentan en la venta?","o":["a) La del licenciado y la de la ventera","b) La del Zurdo y la de su cuñado","c) La del ciego, impresa en un pliego, y la del arriero Cosme, contada sin papel","d) Dos pliegos distintos comprados en la feria"],"c":2},{"t":"Cervantes","q":"¿Cómo se resuelve la disputa sobre cuál de las dos relaciones se sostiene?","o":["a) El licenciado consulta un libro de Salamanca","b) Se le pide al muchacho repetir su pliego sin papel, y se atranca, mientras el arriero dice la suya entera","c) La ventera decide a favor del que paga las velas","d) Se llama al alcalde del pueblo de al lado"],"c":1},{"t":"Cervantes","q":"¿Qué consejo da la ventera, y por cuánto dice que lo vende?","o":["a) Que se imprima el pliego en Medina, por un real","b) Que entre renglón y renglón se ponga pero, por eso o y entonces, y el consejo va de balde porque la lumbre no","c) Que se pregunte al Zurdo, gratis","d) Que se guarde el pliego para el año siguiente, por dos maravedís"],"c":1},{"t":"Cervantes","q":"De los ocho renglones del pliego, ¿cuántos admitían «pero» o «por eso», y en qué quedó la relación?","o":["a) Cinco, y quedó una relación de seis líneas","b) Ninguno, y el pliego se rompió","c) Dos, y quedó una relación de tres líneas que el ciego dijo que vendería a cuatro maravedís","d) Todos, y el pliego quedó igual"],"c":2},{"t":"Cervantes","q":"El arriero pregunta qué pasa si mañana se averigua que la soga la cortó un lobo. ¿Qué le contesta el licenciado?","o":["a) Que su relación quedaría en mentira y habría que callarla","b) Que quedaría en relación equivocada, se corrige con un porque nuevo y se sigue andando","c) Que eso no puede ocurrir porque el agua no corta sogas","d) Que habría que pagarle al forastero preso"],"c":1},{"t":"Harari","q":"Según el ensayo, ¿qué contienen las tablillas más antiguas que sabemos leer, salidas de Uruk?","o":["a) La creación del mundo","b) La muerte de un rey y su entierro","c) Cantos religiosos","d) Inventarios: cebada, ovejas, jornales, cántaros de cerveza"],"c":3},{"t":"Harari","q":"¿Cuál es la razón que el ensayo da para que la escritura naciera como contabilidad y no como narración?","o":["a) Porque las cifras eran más importantes que las historias","b) Porque no existía todavía un alfabeto capaz de contar historias","c) Porque los escribas cobraban por cuenta y no por relato","d) Porque las listas no se pegan a la memoria y las historias sí, así que solo las listas hubo que escribirlas"],"c":3},{"t":"Harari","q":"¿Qué precisaron Trabasso y van den Broek en 1985 respecto del hallazgo de Bower y Clark?","o":["a) Que el efecto solo aparecía en niños","b) Que dentro de un mismo relato los sucesos con más conexiones causales se recuerdan mejor, así que lo que ayuda es la causa","c) Que las listas se recuerdan igual que las historias","d) Que el experimento de 1969 no se pudo replicar"],"c":1},{"t":"Harari","q":"¿Con qué etiqueta de estatus entra en el ensayo el estudio de Kidd y Castano (2013)?","o":["a) Clásico sólido y fundacional","b) Divulgación con inflado sin base experimental","c) Hallazgo replicado y poco discutido","d) Hallazgo famoso con réplica fallida, porque Panero y colegas (2016) no consiguieron replicarlo"],"c":3},{"t":"Harari","q":"¿Cuál es, según el ensayo, el paralelo entre Uruk y nuestro siglo?","o":["a) Que escribimos inventarios, como ellos, pero además los contamos en voz alta y esperamos que se recuerden","b) Que seguimos usando tablillas de barro en forma de pantallas","c) Que nuestras cifras son menos fiables que las suyas","d) Que ellos contaban historias y nosotros ya no sabemos hacerlo"],"c":0},{"t":"Entrevista","q":"¿Por qué dice Forster que conviene saber lo de su tía abuela antes de tomarlo por sabio?","o":["a) Porque ella le enseñó a escribir novelas","b) Porque le dejó un legado que le pagó Cambridge y años de no tener que ganarse la vida, y él escribió sobre gente que no podía permitirse hablar","c) Porque fue el modelo de un personaje suyo","d) Porque ella le prohibió publicar «Maurice»"],"c":1},{"t":"Entrevista","q":"¿Qué dice Forster que la sala de Trinity College esperaba de él, y qué llevó en su lugar?","o":["a) Esperaban una novela nueva, y él llevó unas conferencias","b) Esperaban una defensa de la novela inglesa, y él llevó una crítica","c) Esperaban un manual de escritura, y él llevó una autobiografía","d) Esperaban una clasificación de escuelas y periodos, y él llevó una prueba que se la puede hacer cualquiera"],"c":3},{"t":"Entrevista","q":"¿Cuál es, según la entrevista, la mitad de su idea que casi nadie recoge al citarlo?","o":["a) Que el relato es superior a la trama","b) Que la trama solo funciona en las novelas largas","c) Que él no dijo que la trama sea mejor, sino que es más difícil y más frágil, porque se estropea con un solo porque falso","d) Que las dos frases del rey y la reina no son suyas"],"c":2},{"t":"Entrevista","q":"¿Qué relación establece Forster entre el epígrafe «Only connect» de «La mansión» (1910) y la trama?","o":["a) Que el epígrafe se lo sugirió un editor y no significa nada","b) Que el epígrafe habla solo de política y no de novelas","c) Que es la misma operación: dos cosas que estaban sueltas y alguien que las ata","d) Que lo escribió después de las conferencias de 1927"],"c":2},{"t":"Entrevista","q":"¿Qué paralelo señala Forster entre su propio silencio de cuarenta y seis años y lo que explicó en la tarima?","o":["a) Que sus novelas también se quedaron sin final","b) Que el público inglés prefería el relato a la trama","c) Que la gente tuvo un relato («dejó de escribir») y no tuvo la trama («por qué»), que estaba en un cajón","d) Que sus conferencias fueron su última obra"],"c":2},{"t":"Quintero y Gala","q":"¿Qué contesta Gala a la primera pregunta de Quintero, «¿qué es lo que no se dice?»","o":["a) Que es lo único que se escucha, y que el público se inclina cuando alguien está a punto de decir algo y no lo dice","b) Que es lo que se calla por prudencia","c) Que no se dice lo que no se sabe","d) Que en el teatro todo se dice y nada se calla"],"c":0},{"t":"Quintero y Gala","q":"¿Qué dice Gala que le enseñó el Derecho, que estudió en Sevilla y no ejerció?","o":["a) Que un pleito es una historia contada dos veces con los mismos hechos, y que gana el que ata mejor","b) A hablar en público sin miedo","c) A escribir con frases cortas","d) Que la verdad siempre se impone al final"],"c":0},{"t":"Quintero y Gala","q":"Según Gala, ¿qué diferencia hay entre el público del «¿y luego?» y el del «¿por qué?»","o":["a) El primero paga más entradas","b) El primero aplaude por educación; el segundo sale discutiendo y a los tres días lo cuenta","c) El segundo se aburre antes","d) No hay diferencia, solo edad"],"c":1},{"t":"Quintero y Gala","q":"¿Dónde tuvo que poner Gala el hueco en «Anillos para una dama», y por qué?","o":["a) En el final, porque nadie conocía la historia","b) En el primer acto, porque el segundo era demasiado largo","c) En el reparto, porque los actores eran desconocidos","d) En qué le cuesta, porque el público llevaba ocho siglos sabiendo cómo acaba la historia de la viuda del Cid"],"c":3},{"t":"Quintero y Gala","q":"¿Qué explicación da Gala del silencio de Quintero?","o":["a) Que es el hueco convertido en tiempo, y que lo que el otro dice a los cuatro segundos no se parece a lo que iba a decir en el primero","b) Que es una manera de descansar la voz","c) Que sirve para que el público aplauda","d) Que es una técnica de radio que en teatro no funciona"],"c":0},{"t":"Debate","q":"¿Cuál es la pregunta en disputa del careo, escrita por la moderación antes de empezar?","o":["a) Si el conflicto es un requisito de toda narración o una convención de una tradición convertida en ley","b) Si el conflicto funciona o no funciona","c) Si las estructuras narrativas se pueden enseñar","d) Si Aristóteles tenía razón sobre la tragedia"],"c":0},{"t":"Debate","q":"¿Qué argumento de memoria usa la defensa a favor del obstáculo?","o":["a) Que Trabasso y van den Broek (1985) mostraron que los sucesos con más conexiones causales se recuerdan mejor, y el obstáculo es la máquina más barata de fabricarlas","b) Que el público recuerda mejor a los villanos","c) Que Bower y Clark midieron el efecto del conflicto","d) Que Freytag lo demostró en 1863 con la pirámide"],"c":0},{"t":"Debate","q":"¿Qué caso «duro y geográfico» presenta la objeción?","o":["a) La tragedia griega, que no tenía antagonistas","b) El kishotenketsu, la estructura de cuatro partes de Asia oriental cuyo tercer movimiento es un giro y no un choque","c) La novela europea del siglo XIX","d) El teatro isabelino"],"c":1},{"t":"Debate","q":"¿Qué le concede la defensa a la objeción en sus réplicas?","o":["a) Que el conflicto no sirve para nada","b) Que Le Guin refutó a Aristóteles","c) Que el kishotenketsu se concede entero y que el límite del corpus de Gutenberg se acepta sin discutir, y por eso no sostiene su tesis en ese estudio","d) Que las seis formas de 2016 son falsas"],"c":2},{"t":"Debate","q":"¿Qué dato dice la moderación que resolvería la disputa?","o":["a) Medir arcos y patrones sobre un corpus que no sea casi todo occidental y en inglés, con tradiciones orales, de Asia oriental y mesoamericanas dentro","b) Una encuesta a guionistas profesionales","c) Un experimento de laboratorio con lectores","d) Releer la «Poética» con métodos modernos"],"c":0}];
const lectCompletarBank=[{"t": "Borges", "q": "«El parecido no sabe contar», no; en este cuento la frase que Sotelo anota es que ha escrito un ___ y creía que escribía una historia.", "a": "calendario"}, {"t": "Borges", "q": "Rosaura Andrade decía que el caballo del alcalde había muerto de sed ___ el alcalde había mandado cerrar la acequia.", "a": "porque"}, {"t": "Cervantes", "q": "El ciego vendía sus relaciones de sucesos a dos ___ el pliego.", "a": "maravedís"}, {"t": "Cervantes", "q": "El licenciado dice que el pliego son ocho hechos puestos en fila como cebollas en una ristra, y que la del arriero es una ___.", "a": "cadena"}, {"t": "Harari", "q": "Las tablillas más antiguas que sabemos leer salieron de ___, en la baja Mesopotamia.", "a": "Uruk"}, {"t": "Harari", "q": "Reagan y colegas midieron el arco emocional de mil trescientas veintisiete obras del Proyecto ___.", "a": "Gutenberg"}, {"t": "Entrevista", "q": "Ante «el rey murió y luego murió la reina», el que escucha pregunta «¿y después?»; ante la misma frase con «de pena», pregunta «¿___ qué?».", "a": "por"}, {"t": "Entrevista", "q": "El epígrafe de «La mansión» (1910) son dos palabras: «Only ___».", "a": "connect"}, {"t": "Quintero y Gala", "q": "Gala dice que el silencio es el hueco convertido en ___.", "a": "tiempo"}, {"t": "Quintero y Gala", "q": "Una columna de periódico son setecientas ___ y no admite calentamiento, según Gala.", "a": "palabras"}, {"t": "Debate", "q": "La objeción sostiene que se ha confundido una herramienta muy buena con una ___ de la naturaleza.", "a": "ley"}, {"t": "Debate", "q": "En el terreno común, las dos partes aceptan que el hueco es más básico que el ___.", "a": "conflicto"}];
const lectAnalisisBank=[{"t": "Borges", "q": "Sotelo tenía razón al desconfiar del «porque» de la señora Andrade, y el cuento no resuelve esa tensión. Explica qué gana y qué pierde cada uno de los dos métodos, y qué haría falta para quedarse con lo bueno de los dos.", "guia": "Se valora que la respuesta no elija bando a la ligera: el cuento dice expresamente que Sotelo tenía razón, porque un porque puede ser falso (el caballo pudo morir de una cólica y la acequia no tener nada que ver). Sotelo gana exactitud y pierde memoria; la Andrade gana memoria y arriesga inventar una causa. Una respuesta buena señala que la salida no es renunciar a la causa sino escribirla como lo que es, comprobable y corregible, y quien lo vea puede apoyarse en el remate del capítulo cervantino de esta misma misión: una relación equivocada se corrige con un porque nuevo, mientras un pliego que no afirma nada no se puede ni desmentir. Se valora también quien note que el cuaderno cuarenta y dos es una rendición y no una derrota."}, {"t": "Borges", "q": "El niño contesta «del obispo no hay nada» aunque había seis líneas verdaderas en el cuaderno diecinueve. Explica qué está midiendo esa escena y qué consecuencia tiene para cualquiera que tenga que informar de algo importante.", "guia": "Se valora que se identifique lo que la escena mide: no la verdad de las seis líneas, sino su capacidad de quedarse en la cabeza de alguien. La frase clave del cuento es que lo que no se ata a nada no se guarda en ninguna parte, y que la memoria de un pueblo no es un archivo sino una cadena. Una respuesta buena saca la consecuencia práctica sin exagerarla: informar no es solamente dejar constancia, y una verdad que nadie recuerda hace en el mundo el mismo oficio que una mentira que nadie oyó, como dice el licenciado en la otra lectura. Se valora especialmente quien añada el límite honrado: esto no autoriza a inventar causas para que algo se recuerde."}, {"t": "Cervantes", "q": "La prueba que zanja la disputa de la venta no es un argumento sino un experimento casero: pedirle al muchacho que repita su pliego sin papel. Explica por qué esa prueba es más fuerte que cualquier razonamiento y qué la vuelve comprobable por cualquiera.", "guia": "Se valora que se vea la estructura de la prueba: los dos textos hablan del mismo suceso, el muchacho había leído el suyo cuarenta veces y el arriero había oído el suyo una sola vez y en la cuadra. Al quitar el papel se mide exactamente lo que se discutía, si la relación se agarra o no. Una respuesta buena señala también la segunda mitad del argumento del licenciado, la del orden: el pliego se puede leer en cualquier orden y da lo mismo, y eso es la señal de que dentro no hay historia, mientras que al arriero se le cae todo si se le muda un renglón de sitio. Se valora quien proponga hacer esa misma prueba con un texto propio."}, {"t": "Cervantes", "q": "El licenciado avisa de que también se puede pecar por atar demasiado, y cita el reproche de Cipión a Berganza. Explica en qué consiste ese exceso contrario y por qué el capítulo lo mete justo después de haber defendido la cadena.", "guia": "Se valora que se entienda el aviso como un freno y no como una contradicción: la cadena es lo que hace que una relación se agarre, y a la vez convertir cada casualidad en un porque es como se levantan las calumnias, que es lo que estuvo a punto de costarle cuatro meses de celda al forastero. Una respuesta buena relaciona esto con el remate del lobo: una causa se pone como hipótesis corregible, no como sentencia. Y se valora quien vea por qué el aviso llega en ese momento del capítulo, que es cuando el lector ya está convencido y por tanto en el punto exacto en que un consejo bueno se vuelve peligroso."}, {"t": "Harari", "q": "El ensayo sostiene que la escritura nació para hacer listas porque las listas no se pegan. Explica el razonamiento completo y di qué consecuencia saca para el presente, con al menos dos de los estudios que cita.", "guia": "Se valora que la cadena del razonamiento quede entera: lo que se cae de la memoria son las cifras, no las historias, así que la contabilidad hubo que escribirla y el poema pudo viajar hablado. Se valora que se apoye en dos estudios citados con lo que de verdad dicen, y no más: Bower y Clark (1969) para el efecto de encadenar, y Trabasso y van den Broek (1985) para precisar que lo que ayuda es la causa. Se valora que la consecuencia para el presente se diga como la dice el ensayo, que hoy escribimos inventarios y además los contamos en voz alta esperando que se recuerden. Y se valora mucho quien recoja la pregunta final del ensayo como herramienta: entre estas dos cosas que estoy diciendo, ¿hay una causa o solamente hay un calendario?"}, {"t": "Harari", "q": "El ensayo pone etiqueta de estatus a cada estudio, y con dos de ellos es explícitamente incómodo. Explica qué gana un texto divulgativo al hacer eso y qué habría pasado si el ensayo hubiera citado solo la mitad que le convenía.", "guia": "Se valora que se identifiquen los dos casos incómodos con precisión: el acoplamiento cerebral de Stephens, Silbert y Hasson (2010), etiquetado como hallazgo real sistemáticamente inflado en la prensa y del que se aclara que es correlación; y Kidd y Castano (2013) con la réplica fallida de Panero y colegas (2016). Una respuesta buena explica que la etiqueta permite usar el hallazgo sin prometer lo que no sostiene, y recoge la frase del propio ensayo: quien cite el primero sin el segundo está haciendo, con un estudio sobre narración, exactamente lo que la narración hace mejor, contar la mitad que le conviene. Se valora quien conecte esto con la regla de oro de la ruta, que ninguna estructura ni hallazgo entra sin autor, año y crítica."}, {"t": "Entrevista", "q": "Forster insiste en que él no dijo que la trama sea mejor, sino que es más difícil y más frágil. Explica qué cambia en la práctica esa corrección, y cómo se relaciona con su consejo final de no explicar todo al principio.", "guia": "Se valora que se entienda la fragilidad como una propiedad concreta: un relato no se puede estropear porque no promete nada, y una trama se estropea con un solo porque falso, y entonces el lector la abandona con más rencor del que habría tenido sin la promesa. Una respuesta buena traduce eso a una práctica: atar hechos obliga a que las causas sean verdaderas, así que la técnica aumenta la responsabilidad en vez de reducirla. Se valora la conexión con el consejo final, porque abrir un hueco es también una promesa: dejar que a la otra persona le falte algo compromete a cerrarlo, y el que abre un hueco y no lo cierra hace el mismo daño que el porque falso."}, {"t": "Entrevista", "q": "La pieza declara en su etiqueta que el encuentro nunca ocurrió, porque Forster murió en 1970 y «A fondo» empezó en 1976. Explica por qué esa declaración es obligatoria en esta casa y qué se perdería si se quitara.", "guia": "Se valora que se distinga con claridad lo inventado de lo comprobable: el encuentro y las palabras son invención de la casa, y las obras, fechas y datos biográficos (el legado de Marianne Thornton, las conferencias Clark de 1927, «Pasaje a la India» de 1924, «Maurice» publicada en 1971, el epígrafe de 1910, y las señas de Joaquín Soler Serrano con «A fondo», 1976 a 1981) son reales y verificables. Una respuesta buena explica que sin la declaración el texto se convertiría en una fuente falsa, y que este es el caso más grave posible dentro de esta materia, porque el storytelling es justamente la habilidad con la que se hace pasar una invención por un dato. Se valora quien señale que la etiqueta viaja también en la hoja impresa, porque una hoja suelta se fotocopia y viaja sola."}, {"t": "Quintero y Gala", "q": "Gala distingue dos maneras de que a alguien le falte algo: no saber cómo acaba, y saberlo pero no saber cómo se va a soportar. Explica la diferencia con el reparto de los tres huecos de esta etapa y por qué él dice que la segunda dura más.", "guia": "Se valora que se sitúe la primera manera en el suspenso, el hueco de futuro, y que se vea que la segunda no cabe limpiamente en las tres casillas: es un hueco de futuro sobre el coste y no sobre el desenlace, que es la aportación de oficio de esta lectura. Una respuesta buena recoge su argumento de duración con el caso concreto de «Anillos para una dama» (1973), donde el público llevaba ocho siglos conociendo el final, y su frase de que en la vida sabemos todos cómo acaba y aquí seguimos mirando. Se valora quien conecte esto con el aviso de la etapa sobre la sorpresa, que se gasta en un segundo, y quien saque una consecuencia propia para contar algo cuyo final el que escucha ya conoce."}, {"t": "Quintero y Gala", "q": "Gala dice que un lector que protesta porque no entiende es un lector que está leyendo. Explica qué defiende con eso, qué riesgo tiene ese consejo y dónde está el límite.", "guia": "Se valora que se entienda lo que defiende: entrar por la mitad de la escena, sin calentamiento, y confiar en que el lector complete, que es la misma idea del hueco de Loewenstein aplicada a setecientas palabras. Se valora que se nombre el riesgo sin adornarlo: no toda confusión es un hueco, y un texto simplemente mal escrito también produce protestas, así que la señal de Gala no distingue por sí sola una cosa de la otra. Una respuesta buena propone un límite comprobable, por ejemplo que el hueco se pueda escribir en una frase antes de escribir el texto, y que a los tres párrafos el lector sepa de qué se le hablaba, como dice el propio Gala. Se valora quien recuerde que él habla desde un medio con lectores fieles y que el consejo no se traslada igual a un mensaje que se lee una sola vez."}, {"t": "Debate", "q": "La defensa propone que si «conflicto» significa que la expectativa del lector se rompe, entonces el kishotenketsu también lo tiene y la disputa se reduce a una palabra mal elegida. La objeción llama a eso estirar la palabra hasta que deje de poder ser falsa. Toma partido y defiéndelo, o explica por qué la disputa no se puede cerrar así.", "guia": "Se valora que la respuesta reconozca lo que está en juego, que es si la tesis sigue siendo refutable: una definición que abarca todo deja de decir algo, y ese es un argumento serio y no una salida retórica. Se valora quien note que el careo ya recoge las dos concesiones importantes, la defensa concediendo el kishotenketsu y el límite del corpus de Gutenberg, y la objeción concediendo que la ruptura de expectativa aparece en casi todo lo que se cuenta. Una respuesta buena toma partido con una razón y no con una preferencia, y aguanta la regla del acero antes del juicio: la postura contraria queda escrita en su mejor versión. Se valora también quien recuerde el coste práctico que menciona la objeción, el de salir a buscar villanos e inventar antagonistas en material verdadero."}, {"t": "Debate", "q": "El careo termina diciendo qué dato resolvería la disputa y reconociendo que el método ya existe pero falta el corpus. Explica por qué eso es un buen cierre para un desacuerdo abierto, y qué enseña sobre cómo esta casa cita el estudio de 2016.", "guia": "Se valora que se entienda la forma del cierre: no se declara ganador, se nombra la prueba que decidiría, y esa prueba es del mismo tipo que la ya publicada, medir arcos y patrones sobre un corpus que no sea casi todo occidental y en inglés, con tradiciones orales, de Asia oriental y mesoamericanas. Una respuesta buena explica que así el desacuerdo queda accionable en vez de eterno, y que mientras tanto la casa se queda con lo que las dos partes firman, el conflicto como herramienta más fiable y el hueco como requisito. Se valora quien vea que esto obliga a citar el estudio de Reagan y colegas (2016) siempre con su límite de corpus, y que ese es exactamente el modo de citar que la regla de oro de la ruta exige para todo lo demás."}];
/* Las tres baterías de pantalla las monta ahora js/lecturas.js dentro de
   cada lectura, leyendo estos mismos bancos por su etiqueta de voz. */

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso. Con las dos
// entrevistas la etiqueta crece: además del pastiche hay que declarar que el
// encuentro nunca ocurrió, porque una hoja suelta se fotocopia y viaja sola,
// y una entrevista apócrifa sin declarar es un parte falso con buena cara.
const LECTURAS_IMPR={
  borges:{titulo:'El cronista de Pueblo Exacto',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'Donde se cuenta la disputa que hubo en una venta del camino de Sevilla sobre cuál de dos relaciones de un mismo robo era la verdadera, y de cómo la sentenció un arriero que no sabía leer',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'La especie que no soportaba las listas',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  entrevista:{titulo:'El hombre que dio una prueba en vez de una regla',tipo:'Entrevista imaginada con E. M. Forster, a la manera de Joaquín Soler Serrano',ficcion:true},
  gala:{titulo:'Lo que no se dice',tipo:'El Loco de la Colina: Jesús Quintero conversa con Antonio Gala (conversación imaginada)',ficcion:true},
  debate:{titulo:'¿Necesita toda historia un conflicto?',tipo:'Careo: las dos posturas de una disputa abierta, con sus réplicas',careo:true},
};
function _etiquetaImpresa(meta){
  if(meta&&meta.careo){
    return '<div class="etiqueta"><strong>⚖️ Careo escrito por la casa sobre una disputa real.</strong> Los turnos los firman los <strong>papeles</strong> (moderación, defensa, objeción) y no personas: aquí no se le pone a nadie una palabra en la boca. Los investigadores se citan en tercera persona como fuentes, <strong>toda obra, revista, fecha y cifra es real y comprobable</strong>, y cada postura va escrita en su mejor versión, no en la que sería fácil de tumbar.</div>';
  }
  if(meta&&meta.ficcion){
    return '<div class="etiqueta"><strong>⚠️ Entrevista imaginada: ejercicio de estilo de la casa, en homenaje.</strong> El encuentro <strong>nunca ocurrió</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando las voces. Las personas son reales, <strong>toda obra, fecha y cifra citada es real y comprobable</strong>, y lo único inventado es la conversación.</div>';
  }
  return '<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.</div>';
}
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · La cadena y el hueco · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#4a1220;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#b1263f;border-bottom:1.5pt solid #b1263f;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #b1263f;background:#fdf2f4;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#4a1220;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#b1263f;background:#fdf2f4;border-left:3pt solid #b1263f;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#b1263f;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
${FaroMarcador.cssImpresion()}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Storytelling</span><span>🧵 La cadena y el hueco${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🧵 Ruta del Hilo que Tira · Etapa 1 de 12</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +_etiquetaImpresa(meta)
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  const _ap=window.FaroLecturas;
  const preg=(_ap&&_ap.preguntasImpresas)?_ap.preguntasImpresas(clave):'';
  const _cuerpo=(_ap&&_ap.etiquetaCareo)?_ap.etiquetaCareo(clave,cuerpo):cuerpo;
  _abreImpresion(_hojaImpresa(meta.titulo,_cuerpo+preg+FaroMarcador.impresionExtra([clave]),' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🧵 Ruta del Hilo que Tira · Etapa 1 de 12</span><span>Las seis lecturas 📖</span></div>`
    +`<h1>Las seis lecturas de «La cadena y el hueco»</h1><div class="tipo">Un cuento, un capítulo, un ensayo, dos entrevistas imaginadas y un careo, sobre las mismas dos piezas</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco primeros <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>, el sexto es un careo escrito por la casa sobre una disputa real, y las dos entrevistas son <strong>imaginadas: los encuentros nunca ocurrieron</strong>. La entrevista de la casa y la conversación entre Jesús Quintero y Antonio Gala son invención del Proyecto Educativo F.A.R.O., que se declara como pastiche. Las personas son reales y <strong>toda obra, fecha y cifra citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala','debate'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las seis lecturas',cuerpo+FaroMarcador.impresionExtra(null),' · Las seis lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🧵 Ruta del Hilo que Tira · Etapa 1 de 12</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las seis lecturas</h1><div class="tipo">La cadena y el hueco · 30 de comprensión lectora, 12 de completar y 12 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los seis textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco primeros son <strong>ejercicios de estilo de la casa</strong>: no son obra de Borges, Cervantes ni Harari, y las dos entrevistas son imaginadas (los encuentros nunca ocurrieron). El sexto es un <strong>careo</strong> sobre una disputa real, con los turnos firmados por papeles y no por personas.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (30 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (12 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (12 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

